<?php
namespace App\Http\Controllers; use App\Models\MembershipLevel; use Illuminate\Http\Request; use Illuminate\Validation\Rule;
class LevelController extends Controller { public function index(){return view('levels.index',['levels'=>MembershipLevel::withCount('members')->paginate(12)]);} public function create(){return view('levels.form',['level'=>new MembershipLevel(['is_active'=>true,'validity_months'=>12])]);} public function store(Request $r){MembershipLevel::create($r->validate(['name'=>'required|max:100|unique:membership_levels','fee'=>'required|numeric|min:0','validity_months'=>'required|integer|min:1','benefits'=>'nullable','is_active'=>'boolean']));return redirect()->route('levels.index')->with('success','Level created.');} public function edit(MembershipLevel $level){return view('levels.form',compact('level'));} public function update(Request $r,MembershipLevel $level){$level->update($r->validate(['name'=>['required','max:100',Rule::unique('membership_levels','name')->ignore($level)],'fee'=>'required|numeric|min:0','validity_months'=>'required|integer|min:1','benefits'=>'nullable','is_active'=>'boolean']));return redirect()->route('levels.index')->with('success','Level updated.');} public function destroy(MembershipLevel $level){if($level->members()->exists())return back()->with('error','A level assigned to members cannot be deleted.');$level->delete();return back()->with('success','Level deleted.');} }
